-- Penal: Teoria do Crime
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-456', 'O crime, no direito penal, e:', '["Apenas a conduta tipica.","A conduta tipica, ilicita e culpavel.","Apenas a conduta ilicita.","Apenas a conduta culpavel.","Apenas o resultado."]'::jsonb, 1, 'O crime e a conduta tipica, ilicita e culpavel.', 'easy', 'Teoria do crime', 'multiple_choice', 'published', 5525, 'CEBRASPE', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-457', 'A tipicidade formal exige que a conduta se enquadre:', '["Na lei penal, conforme a descricao legal do tipo.","Na vontade do juiz.","No costume.","Na analogia.","Na equidade."]'::jsonb, 0, 'A tipicidade formal exige que a conduta se enquadre na descricao legal do tipo.', 'medium', 'Tipicidade', 'multiple_choice', 'published', 5526, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-458', 'A tipicidade material exige que a conduta seja:', '["Socialmente irrelevante.","Socialmente relevante e lesiva ao bem juridico.","Apenas tipica formalmente.","Apenas ilicita.","Apenas culpavel."]'::jsonb, 1, 'A tipicidade material exige que a conduta seja socialmente relevante e lesiva ao bem juridico.', 'medium', 'Tipicidade', 'multiple_choice', 'published', 5527, 'FGV', 'OAB'),
