((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-461', 'A culpa consciente ocorre quando o agente:', '["Nao prevê o resultado.","Prevê o resultado, mas confia que nao ocorra.","Quer o resultado.","Assume o risco.","Age por dolo."]'::jsonb, 1, 'A culpa consciente ocorre quando o agente prevê o resultado, mas confia que nao ocorra.', 'medium', 'Culpa', 'multiple_choice', 'published', 5530, 'FCC', 'Tribunais'),
