((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-464', 'O inimputavel, em regra:', '["Responde penalmente de forma integral.","Nao responde penalmente, podendo ser submetido a medida de seguranca.","Responde apenas por crimes leves.","Responde apenas por crimes graves.","Responde com pena reduzida."]'::jsonb, 1, 'O inimputavel nao responde penalmente, podendo ser submetido a medida de seguranca.', 'medium', 'Imputabilidade', 'multiple_choice', 'published', 5533, 'CEBRASPE', 'OAB'),
